CREATE proc [dbo].[uspReportOpenBalanceOfDepartment] @Did as int as if @Did > 0 begin select opm.OpenInvId,'' as Dept,opm.Date,opm.type,i.ItemId,i.Item,u.Unit,opd.Qty,opd.Rate,opd.Amount from OpenInventoryMaster_department opm inner join OpenInventoryDetail_department opd on opm.OpenInvId = opd.OpenInvId inner join Item i on opd.ItemId = i.ItemId inner join ItemUnit iu on i.ItemId = iu.ItemId inner join Unit u on iu.PurUnit = u.UId where opm.did = @Did and opm.OpenInvId = (select max (OpenInvId) from OpenInventoryMaster_Department) order by opm.OpenInvId desc end else begin  select opm.OpenInvId,'' as Dept,opm.Date,opm.type,i.ItemId,i.Item,u.Unit,opd.Qty,opd.Rate,opd.Amount  from OpenInventoryMaster_department opm inner join OpenInventoryDetail_department opd on opm.OpenInvId = opd.OpenInvId inner join Item i on opd.ItemId = i.ItemId inner join ItemUnit iu on i.ItemId = iu.ItemId inner join Unit u on iu.PurUnit = u.UId where  opm.OpenInvId = (select max (OpenInvId) from OpenInventoryMaster_Department) order by opm.OpenInvId desc  end